    }
    case 'drill_repair': {
      const ok = sims.map((s) => s.drill.repairRig(a)).some(Boolean);
      return ok ? `отмена поломки ${ref.drill.rigs[a]?.name}` : `${ref.drill.rigs[a]?.name ?? a} не в ремонте`;
